package tests;

import org.openqa.selenium.By;
import org.openqa.selenium.JavascriptExecutor;
import org.openqa.selenium.WebDriver;
import org.openqa.selenium.WebElement;
import org.openqa.selenium.chrome.ChromeDriver;

import java.time.Duration;

public class JavaScriptExecutorDemo {


    static String veryLengthy = "";

    public static void main(String[] args) {

        long startTime = System.currentTimeMillis();
        veryLengthy = veryLengthy +veryLengthy;
        WebDriver driver = new ChromeDriver();
        driver.manage().timeouts().pageLoadTimeout(Duration.ofSeconds(20));
        driver.get("file:///Users/vaibhavsingh/Desktop/teche-apps/merv/ey-automation-testing/test2.html");

        //driver.findElement(By.id("txt")).sendKeys(veryLengthy);

        WebElement txtBox = driver.findElement(By.id("txt"));
//       WebElement googleLink = driver.findElement(By.xpath("//a[text()='Google']"));
        ((JavascriptExecutor)driver).executeScript("arguments[0].value='"+veryLengthy+"'", txtBox);
        long endTime = System.currentTimeMillis();
        System.out.println("script time (ms) :  " + (endTime - startTime));

        //22515 - sendKeys
        //3845  -
    }
}
